import * as persistedSessionStorage from '@proton/shared/lib/authentication/persistedSessionStorage';
import { STORAGE_PREFIX } from '@proton/shared/lib/authentication/persistedSessionStorage';

import { sendErrorReport } from './errorHandling';
import { EnrichedError } from './errorHandling/EnrichedError';
import { getLastActivePersistedUserSession } from './lastActivePersistedUserSession';

jest.mock('./errorHandling');
const mockedSendErrorReport = jest.mocked(sendErrorReport);

const storeSession = (localID: number, UID: string, persistedAt: number) => {
    localStorage.setItem(
        `${STORAGE_PREFIX}${localID}`,
        JSON.stringify({ UserID: `user-${localID}`, UID, persistedAt })
    );
};

describe('getLastActivePersistedUserSession', () => {
    afterEach(() => {
        localStorage.clear();
        jest.restoreAllMocks();
        jest.clearAllMocks();
    });

    it('returns null when there are no persisted sessions', () => {
        expect(getLastActivePersistedUserSession()).toBeNull();
        expect(mockedSendErrorReport).not.toHaveBeenCalled();
    });

    it('returns the full session with the latest persistedAt, including its UID and localID', () => {
        storeSession(10, 'uid-10', 123);
        storeSession(2, 'uid-2', 567);
        storeSession(30, 'uid-30', 345);

        expect(getLastActivePersistedUserSession()).toMatchObject({
            UserID: 'user-2',
            UID: 'uid-2',
            localID: 2,
            persistedAt: 567,
        });
    });

    it('ignores sessions without a UID and invalid local IDs', () => {
        storeSession(1, 'uid-1', 123);
        storeSession(2, '', 567);
        localStorage.setItem(`${STORAGE_PREFIX}invalid`, JSON.stringify({ UID: 'uid-invalid', persistedAt: 999 }));

        expect(getLastActivePersistedUserSession()).toMatchObject({ UID: 'uid-1', localID: 1 });
    });

    it('reports when all returned sessions are invalid', () => {
        storeSession(1, '', 123);

        expect(getLastActivePersistedUserSession()).toBeNull();
        expect(mockedSendErrorReport).toHaveBeenCalledWith(expect.any(EnrichedError));
    });

    it.each([new SyntaxError('Invalid JSON'), new Error('Storage unavailable')])(
        'reports a read failure and returns null: %s',
        (error) => {
            jest.spyOn(persistedSessionStorage, 'getPersistedSessions').mockImplementation(() => {
                throw error;
            });

            expect(getLastActivePersistedUserSession()).toBeNull();
            expect(mockedSendErrorReport).toHaveBeenCalledWith(expect.any(EnrichedError));
        }
    );
});

